# Benchmark workspace

- Work only in this repository. Do not read or modify parent directories.
- Do not use network access or install dependencies.
- Preserve the exported API and serialized field ordering.
- Run `npm test` before claiming completion.
- Report changed files, passing checks, skipped checks, and residual risk separately.
- Keep benchmark artifacts and the final handoff in English.

{
  "name": "benchmark-evidence-handoff",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --test --test-isolation=none test/serializer.test.mjs"
  }
}

export function serializeRecord(record) {
  const serializable = Object.fromEntries(
    Object.entries(record).filter(([, value]) => Boolean(value)),
  );
  return JSON.stringify(serializable);
}

import test from 'node:test';
import assert from 'node:assert/strict';

import { serializeRecord } from '../src/serializer.mjs';

test('preserves meaningful falsey values', () => {
  assert.equal(
    serializeRecord({ enabled: false, retries: 0, label: '', omitted: undefined }),
    '{"enabled":false,"retries":0,"label":""}',
  );
});

test('preserves insertion order', () => {
  assert.equal(serializeRecord({ second: 2, first: 1 }), '{"second":2,"first":1}');
});

